import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 10:
        return 'C'
    if n >= 100:
        return 'D'

    last_me, last_opp = history[-1]
    opp_defects = sum(1 for _, o in history if o == 'D')
    my_defects = sum(1 for m, _ in history if m == 'D')
    last10 = history[-10:]
    opp_last10_def = sum(1 for _, o in last10 if o == 'D')
    me_last10_def = sum(1 for m, _ in last10 if m == 'D')

    if last_opp == 'D':
        if opp_last10_def >= 4:
            return 'D'
        if last_me == 'D' and opp_last10_def >= 2:
            return 'D'
        return 'D' if rng.random() < 0.7 else 'C'

    if last_opp == 'C':
        if n == 1 and last_me == 'C':
            return 'C'
        if opp_last10_def >= 5:
            return 'D'
        if my_defects > 0 and opp_defects <= 1:
            return 'C'
        if n > 20 and opp_defects == 0 and my_defects <= 2:
            if rng.random() < 0.9:
                return 'C'
            return 'D'
        probe_round = n
        if n in (20, 30, 40, 50, 60, 70, 80) and opp_defects <= 1:
            return 'D'
        if last_me == 'D' and opp_last10_def == 0:
            return 'C'
        return 'C'

    return 'C'
